package com.leotv.detail;
import android.app.Activity;import android.view.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=23,manifest=Config.NONE)
public class HomeBookmarkTest {
 Activity activity;HomeBookmarkSubject page;HomeBookmarkSubject.Shelf first,second;
 @Before public void open(){activity=Robolectric.buildActivity(Activity.class).setup().get();page=new HomeBookmarkSubject(activity);first=page.new Shelf();second=page.new Shelf();activity.setContentView(page);page.measure(View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));page.layout(0,0,800,600);}
 @Test public void enteringDetailDoesNotFlashBackToTheFirstCard(){View selected=first.rail.getChildAt(5);assertTrue(page.focusHome(selected));int x=first.viewport.getScrollX();assertTrue(x>0);assertEquals(5,first.selected);page.active(false);assertTrue(selected.hasFocus());assertEquals(x,first.viewport.getScrollX());assertEquals(5,first.selected);page.active(true);assertEquals(x,first.viewport.getScrollX());assertEquals(5,first.selected);}
 @Test public void leavingTheViewportKeepsEachCategoryOrderAndBookmark(){assertTrue(page.focusHome(first.rail.getChildAt(5)));int x=first.viewport.getScrollX();List<Object> order=new ArrayList<>();for(int i=0;i<first.rail.getChildCount();i++)order.add(first.rail.getChildAt(i).getTag());assertTrue(page.focusHome(second.rail.getChildAt(4)));page.resetOffscreenRows();assertEquals(5,first.selected);assertEquals(x,first.viewport.getScrollX());for(int i=0;i<order.size();i++)assertEquals(order.get(i),first.rail.getChildAt(i).getTag());}
 @Test public void backFirstFocusesTheCategoryStartThenSignalsReturnToTop(){assertTrue(page.focusHome(first.rail.getChildAt(5)));assertTrue(page.focusFirstInRow(page.findFocus()));assertTrue(first.rail.getChildAt(0).hasFocus());assertEquals(0,first.viewport.getScrollX());assertFalse("Second Back must pass to the existing top/site action",page.focusFirstInRow(page.findFocus()));}
 @Test public void backFromTheCategoryHeaderAlsoFocusesItsFirstWork(){assertTrue(first.open.requestFocus());assertTrue(page.focusFirstInRow(first.open));assertTrue(first.rail.getChildAt(0).hasFocus());}
}
